package authcompat

import (
	"encoding/hex"
	"errors"
	"testing"

	"golang.org/x/crypto/bcrypt"
)

func TestVerifyClojureVector(t *testing.T) {
	// Generated by Clojure buddy.hashers:
	// (h/derive "password123" {:alg :bcrypt+sha512 :salt (codecs/hex->bytes "...") :iterations 12})
	encoded := "bcrypt+sha512$4f69f3674b49036f12333a5db32ea405$12$9abfaaa3ff461b8cd035d41190d8013e268837304492dcd7"

	ok, err := Verify("password123", encoded)
	if err != nil {
		t.Fatalf("unexpected verify error: %v", err)
	}
	if !ok {
		t.Fatalf("expected password to verify")
	}

	ok, err = Verify("wrong-password", encoded)
	if err != nil {
		t.Fatalf("unexpected verify error on mismatch: %v", err)
	}
	if ok {
		t.Fatalf("expected mismatch password to fail verification")
	}
}

func TestDeriveAndVerifyRoundTrip(t *testing.T) {
	encoded, err := Derive("hello-mdbrain")
	if err != nil {
		t.Fatalf("derive failed: %v", err)
	}

	ok, err := Verify("hello-mdbrain", encoded)
	if err != nil {
		t.Fatalf("verify failed: %v", err)
	}
	if !ok {
		t.Fatalf("expected derived hash to verify")
	}
}

func TestVerifyLegacyFallback(t *testing.T) {
	password := "legacy-pass"
	saltHex := "4f69f3674b49036f12333a5db32ea405"
	salt, err := hex.DecodeString(saltHex)
	if err != nil {
		t.Fatalf("decode salt: %v", err)
	}

	legacyCandidate := legacyCandidateHex([]byte(password), salt)
	legacyHash, err := bcrypt.GenerateFromPassword([]byte(legacyCandidate[:72]), DefaultCost)
	if err != nil {
		t.Fatalf("legacy bcrypt derive: %v", err)
	}

	encoded := Algorithm + "$" + saltHex + "$12$" + hex.EncodeToString(legacyHash)
	ok, err := Verify(password, encoded)
	if err != nil {
		t.Fatalf("legacy verify error: %v", err)
	}
	if !ok {
		t.Fatalf("expected legacy-compatible hash to verify")
	}
}

func TestParseErrors(t *testing.T) {
	_, err := Verify("x", "invalid")
	if !errors.Is(err, ErrMalformedHash) {
		t.Fatalf("expected ErrMalformedHash, got %v", err)
	}

	_, err = Verify("x", "bcrypt+sha512$abcd$12$ff")
	if !errors.Is(err, ErrMalformedHash) {
		t.Fatalf("expected malformed salt error, got %v", err)
	}

	_, err = Verify("x", "bcrypt+sha512$4f69f3674b49036f12333a5db32ea405$33$ff")
	if !errors.Is(err, ErrInvalidCost) {
		t.Fatalf("expected ErrInvalidCost, got %v", err)
	}
}
